def _replace_error(meth):
    @wraps(meth)
    def wrapper(*meth_args, **meth_kwargs):
        try:
            return meth(*meth_args, **meth_kwargs)
        except TranspilerError:
            raise
        except PassManagerError as ex:
            raise TranspilerError(ex.message) from ex
    return wrapper
