def _transform_to_pauli(data, num_qubits):
    """Change of basis of bipartite matrix representation."""
    basis_mat = np.array(
        [[1, 0, 0, 1], [0, 1, 1, 0], [0, -1j, 1j, 0], [1, 0j, 0, -1]], dtype=complex
    )
    cob = basis_mat
    for _ in range(num_qubits - 1):
        dim = int(math.sqrt(len(cob)))
        cob = np.reshape(
            np.transpose(
