def _should_decompose(self, node: DAGOpNode) -> bool:
        """Call a decomposition pass on this circuit to decompose one level (shallow decompose)."""
        if self.gates_to_decompose is None:
            return True
        if not isinstance(self.gates_to_decompose, list):
            gates = [self.gates_to_decompose]
        else:
            gates = self.gates_to_decompose
        strings_list = [s for s in gates if isinstance(s, str)]
        gate_type_list = [g for g in gates if isinstance(g, type)]
        if (
            getattr(node.op, "label", None) is not None
            and node.op.label != ""
            and (
                node.op.label in gates or any(fnmatch(node.op.label, p) for p in strings_list)
            )
        ):
            return True
        elif node.name in gates or any(
            fnmatch(node.name, p) for p in strings_list
        ):
            return True
        elif any(isinstance(node.op, op) for op in gate_type_list):
            return True
        else:
            return False

def _get_connectivity(num_qubits: int, connectivity: str) -> dict:
    Generates connectivity structure between qubits.
    Args:
        num_qubits: number of qubits.
        connectivity: type of connectivity structure, ``{"full", "line", "star"}``.
    Returns:
        dictionary of allowed links between qubits.
    Raises:
         ValueError: if unsupported type of CNOT-network layout is passed.
    if num_qubits == 1:
        links = {0: [0]}
    elif connectivity == "full":
        links = {i: list(range(num_qubits)) for i in range(num_qubits)}
    elif connectivity == "line":
        # Every qubit is connected to its immediate neighbors only.
        links = {i: [i - 1, i, i + 1] for i in range(1, num_qubits - 1)}
        links[0] = [0, 1]
        links[num_qubits - 1] = [num_qubits - 2, num_qubits - 1]
    elif connectivity == "star":
        links = {i: [0, i] for i in range(1, num_qubits)}
        links[0] = list(range(num_qubits))
    else:
        raise ValueError(
            f"Unknown connectivity type, expects one of {_CONNECTIVITY_TYPES}, got {connectivity}"
        )
    return links

def random_quantum_channel(
    input_dims: int | tuple | None = None,
    output_dims: int | tuple | None = None,
    rank: int | None = None,
    seed: int | np.random.Generator | None = None,
):
    if input_dims is None and output_dims is None:
        raise QiskitError(
            "No dimensions specified: input_dims and output_dims cannot both be None."
        )
    if input_dims is None:
        input_dims = output_dims
    elif output_dims is None:
        output_dims = input_dims
    d_in = np.prod(input_dims)
    d_out = np.prod(output_dims)
    # If rank is not specified set to the maximum rank for the
    # Choi matrix (input_dim * output_dim)
    if rank is None or rank > d_in * d_out:
        rank = d_in * d_out
    if rank < 1:
        raise QiskitError(f"Rank {rank} must be greater than 0.")
    from scipy import stats
    unitary = stats.unitary_group.rvs(max(rank * d_out, d_in), random_state=seed)
    return Stinespring(unitary[:, :d_in], input_dims=input_dims, output_dims=output_dims)

def expectation_value(self, oper: Pauli | SparsePauliOp, qargs: None | list = None) -> complex:
        """Compute the expectation value of a Pauli or SparsePauliOp operator.

        Args:
            oper: A Pauli or SparsePauliOp operator to evaluate the expectation value.
            qargs: Subsystems to apply the operator on.

        Returns:
            The expectation value.

        Raises:
            QiskitError: if oper is not a Pauli or SparsePauliOp operator.
        """
        if isinstance(oper, Pauli):
            return self._expectation_value_pauli(oper, qargs)
        if isinstance(oper, SparsePauliOp):
            return sum(
                coeff * self._expectation_value_pauli(Pauli((z, x)), qargs)
                for z, x, coeff in zip(oper.paulis.z, oper.paulis.x, oper.coeffs)
            )
        raise QiskitError(
            "Operator for expectation value is not a Pauli or SparsePauliOp operator, "
            f"but {type(oper)}."
        )

class _SingletonMeta(type(Instruction)):
    # Beware the difference between `type.__new__` and `type.__call__`.  The former is called during
    # creation of the _type object_ (e.g. during a `class A: ...` statement), and the latter is
    # called by type instantiation (e.g. `A()`).
    __slots__ = ()
    def __new__(mcs, name, bases, namespace, *, overrides=None, **kwargs):
        cls = super().__new__(mcs, name, bases, namespace, **kwargs)
        if overrides is not None:
            cls.__init_subclass__ = _impl_init_subclass(cls, overrides)
        return cls
    def __call__(cls, *args, _force_mutable=False, **kwargs):
        if _force_mutable:
            return super().__call__(*args, **kwargs)
        if not args and not kwargs:
            return cls._singleton_default_instance
        if (key := cls._singleton_lookup_key(*args, **kwargs)) is not None:
            try:
                singleton = cls._singleton_static_lookup.get(key)
            except TypeError:
                singleton = None
            if singleton is not None:
                return singleton
        return super().__call__(*args, **kwargs)

