def _expectation_value_pauli(self, pauli, qargs=None):
        """Compute the expectation value of a Pauli.

        Args:
            pauli (Pauli): a Pauli operator to evaluate expval of.
            qargs (None or list): subsystems to apply operator on.

        Returns:
            complex: the expectation value.
        """
        n_pauli = len(pauli)
        if qargs is None:
            qubits = np.arange(n_pauli)
        else:
            qubits = np.array(qargs)
        x_mask = np.dot(1 << qubits, pauli.x)
        z_mask = np.dot(1 << qubits, pauli.z)
        pauli_phase = (-1j) ** pauli.phase if pauli.phase else 1
        if x_mask + z_mask == 0:
            return pauli_phase * np.linalg.norm(self.data) ** 2
        if x_mask == 0:
            return pauli_phase * expval_pauli_no_x(self.data, self.num_qubits, z_mask)
        x_max = qubits[pauli.x][-1]
        y_phase = (-1j) ** pauli._count_y()
        y_phase = y_phase[0]
        return pauli_phase * expval_pauli_with_x(
            self.data, self.num_qubits, z_mask, x_mask, y_phase, x_max
        )

def run(self, dag):
        indices = {qubit: index for index, qubit in enumerate(dag.qubits)}
        # sorted to so that they are in the order they appear in the DAG
        # so ancestors/descendants makes sense
        barriers = [nd for nd in dag.topological_op_nodes() if nd.name == "barrier"]
        node_to_barrier_qubits = MergeAdjacentBarriers._collect_potential_merges(dag, barriers)
        if not node_to_barrier_qubits:
            return dag
        for barrier in barriers:
            if barrier in node_to_barrier_qubits:
                barrier_to_add, nodes = node_to_barrier_qubits[barrier]
                dag.replace_block_with_op(
                    nodes, barrier_to_add, wire_pos_map=indices, cycle_check=False
                )
        return dag

