def state_fidelity(
    state1: Statevector | DensityMatrix, state2: Statevector | DensityMatrix, validate: bool = True
) -> float:
    # convert input to numpy arrays
    state1 = _format_state(state1, validate=validate)
    state2 = _format_state(state2, validate=validate)
    arr1 = state1.data
    arr2 = state2.data
    if isinstance(state1, Statevector):
        if isinstance(state2, Statevector):
            fid = np.abs(arr2.conj().dot(arr1)) ** 2
        else:
            fid = arr1.conj().dot(arr2).dot(arr1)
    elif isinstance(state2, Statevector):
        fid = arr2.conj().dot(arr1).dot(arr2)
    else:
        s1sq = _funm_svd(arr1, np.sqrt)
        s2sq = _funm_svd(arr2, np.sqrt)
        fid = np.linalg.norm(s1sq.dot(s2sq), ord="nuc") ** 2
    return float(np.real(fid))

def run(self, unitary, **options):
        config = options.get("config") or {}
        min_qubits = config.get("min_qubits", 1)
        max_qubits = config.get("max_qubits", 3)
        num_qubits = int(math.log2(unitary.shape[0]))
        dag = None
        if min_qubits <= num_qubits <= max_qubits:
            try:
                cliff = Clifford.from_matrix(unitary)
                circuit = cliff.to_circuit()
                # Constructing Clifford from a unitary discards the global phase,
                # so we need to reconstruct it.
                props = {}
                if not matrix_equal(
                    unitary, Operator(circuit)._data, ignore_phase=True, props=props
                ):
                    raise QiskitError("Clifford synthesis is incorrect")
                circuit.global_phase -= props["phase_difference"]
                dag = circuit_to_dag(circuit)
            except QiskitError:
                pass
        return dag

def _bitflips_to_timings(row):
    num = len(row)
    distances = []
    count = 0
    last = 0  # start in no flip state
    for el in row:
        if el == last:
            count += 1
        else:
            distances.append(count / num)
            last = el
            count = 1
    distances.append(count / num)
    if len(distances) % 2 == 0:
        return distances + [0]
    return distances

