class WalshHadamardSequence:
    """Get Walsh-Hadamard sequences for DD up to arbitrary order."""
    def __init__(self, max_order: int = 5):
        Args:
            max_order: The maximal order for which the sequences are computed.
        self.sequences = None
        self.max_order = None
        self.set_max_order(max_order)
    def set_max_order(self, max_order: int) -> None:
        if self.max_order is not None:
            if max_order <= self.max_order:
                return
        num_krons = int(np.ceil(np.log2(max_order + 1)))
        self.max_order = 2**num_krons - 1
        rows = _get_transformation_matrix(num_krons).tolist()
        distances = [_bitflips_to_timings(row) for row in rows]
        num_flips = [len(distance) - 1 for distance in distances]
        indices = np.argsort(num_flips)[1:]
        self.sequences = [distances[i] for i in indices]
    def get_sequence(self, order: int) -> list[float]:
        if order > self.max_order:
            self.set_max_order(order)
        return self.sequences[order]

def _find_adjoining_run(dag, runs, run, front=True):
        """
        Finds the run which abuts `run` from the front (or the rear if `front == False`), separated
        by a blocking node.

        Returns a pair of the abutting multiqubit gate and the run which it separates from this
        one. The next run can be the empty list `[]` if it is absent.
        """
        edge_node = run[0] if front else run[-1]
        blocker = next(dag.predecessors(edge_node) if front else dag.successors(edge_node))
        possibilities = dag.predecessors(blocker) if front else dag.successors(blocker)
        adjoining_run = []
        for possibility in possibilities:
            if isinstance(possibility, DAGOpNode) and possibility.qargs == edge_node.qargs:
                adjoining_run = []
                for single_run in runs:
                    if (
                        len(single_run) != 0 and single_run[0].qargs == possibility.qargs
                    ):
                        if possibility in single_run:
                            adjoining_run = single_run
                            break
                break
        return (blocker, adjoining_run)

